-- 1214: C811 "Job Assessment and Redesign for AI Adoption" -- replace the
-- leftover Power Apps body copy.
--
-- Migration 1210 renamed C811 from "PL-7001 Create and manage canvas apps with
-- Power Apps" but left the PL-7001 short_description (What This Course is
-- About) and description (What You Will Learn / course outline) untouched, so
-- the live page still described a Power Apps course.
--
-- This writes:
--   * short_description -- new overview grounded in The Conference Board's
--     "Framework for Agentic AI and Work Redesign" (five decisions: outcome-
--     driven redesign, allocation across three modes, data/governance,
--     capability yield, gain allocation).
--     Ref: https://www.conference-board.org/publications/framework-for-agentic-AI-and-work-redesign
--   * description -- TWO topics (1 day / 7.5h, ~3.75h each), with the matching
--     LSN_DATA JSON comment so the admin outline editor stays in sync with the
--     rendered <p> markup.
--
-- It also fixes the Funding and Grant block, which still linked to the Power
-- Apps WSQ course and carried an invalid-UTF-8 en dash (the mojibake "?" on the
-- live page). It now points at TGS-2024045795 WSQ - Agentic AI for HR.
--
-- Payloads are written as HEX to preserve bytes exactly. Both are pure ASCII
-- (HTML entities, no raw Unicode), so apply.php's utf8 connection is safe.
--
-- SG-guarded; C-prefix SKU is SG-only (partner no-op). Idempotent.

SET @is_sg := (
  SELECT COUNT(*) FROM core_config_data
  WHERE path = 'web/unsecure/base_url'
    AND value LIKE '%tertiarycourses.com.sg%'
);

SET @e811 := (SELECT entity_id FROM catalog_product_entity WHERE sku = 'C811' LIMIT 1);

SET @a_desc  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'description');
SET @a_short := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'short_description');

-- ---------------------------------------------------------------------------
-- 1) What This Course is About (short_description) + corrected funding block.
-- ---------------------------------------------------------------------------

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_short, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

-- Drop any store-scoped override so the store view cannot keep serving the
-- stale PL-7001 copy.
DELETE FROM catalog_product_entity_text
WHERE entity_id = @e811 AND attribute_id = @a_short AND store_id <> 0
  AND @e811 IS NOT NULL AND @is_sg > 0;

-- ---------------------------------------------------------------------------
-- 2) What You Will Learn (description) -- two topics + LSN_DATA.
-- ---------------------------------------------------------------------------

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_desc, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE FROM catalog_product_entity_text
WHERE entity_id = @e811 AND attribute_id = @a_desc AND store_id <> 0
  AND @e811 IS NOT NULL AND @is_sg > 0;

-- ---------------------------------------------------------------------------
-- 3) Mirror into the product flat tables so the storefront reads the new copy
--    without waiting on a reindex.
-- ---------------------------------------------------------------------------

SET @has_flat1 := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_product_flat_1' AND COLUMN_NAME = 'short_description');

SET @sql := IF(@has_flat1 > 0 AND @e811 IS NOT NULL AND @is_sg > 0,
  'UPDATE catalog_product_flat_1 f
     JOIN catalog_product_entity_text t
       ON t.entity_id = f.entity_id AND t.store_id = 0 AND t.attribute_id = @a_short
      SET f.short_description = t.value
    WHERE f.entity_id = @e811',
  'DO 0');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SET @has_flat1d := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_product_flat_1' AND COLUMN_NAME = 'description');

SET @sql := IF(@has_flat1d > 0 AND @e811 IS NOT NULL AND @is_sg > 0,
  'UPDATE catalog_product_flat_1 f
     JOIN catalog_product_entity_text t
       ON t.entity_id = f.entity_id AND t.store_id = 0 AND t.attribute_id = @a_desc
      SET f.description = t.value
    WHERE f.entity_id = @e811',
  'DO 0');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
